let visionEnabled=false,visionContext="",visionController=null;
'use strict';
let analysisActive=null,analysisBusy=false,analysisFilter='',analysisError='',analysisProgress='',analysisPreviewUrl=null,analysisPreviewHTML='',analysisPage=0,readerWorker=null,ocrWorker=null;
const analysisRowsPerPage=50;
function analyses(p=project()){return p.analyses||(p.analyses=[])}
function currentAnalysis(){return analyses().find(a=>a.id===analysisActive)||analyses().at(-1)}
function analysisView(p){const a=currentAnalysis();return `<section class="card card-pad interpret-hero"><div class="card-title"><div><div class="eyebrow">LEITURA DE FICHEIROS · BETA</div><h2 style="font-size:24px;margin-top:10px">Do ficheiro aos dados.</h2></div><span class="badge">OCR local / visão IA opcional</span></div><p class="smalltext muted">Extrai informação, verifica a fonte e só depois leva os dados para o orçamento.</p><label><input type="checkbox" id="vision-enable" onchange="visionEnabled=this.checked" ${visionEnabled?'checked':''}> Interpretar foto ou esquiço com IA (envia a imagem e o texto ao fornecedor de IA configurado no servidor)</label><label>Contexto do pedido<textarea class="field" id="vision-context" oninput="visionContext=this.value" placeholder="Ex.: portão de duas folhas; medidas indicadas pelo cliente…">${esc(visionContext)}</textarea></label><label class="analysis-drop ${analysisBusy?'busy':''}"><span style="font-size:25px;color:var(--green)">↥</span><strong>${analysisBusy?'A interpretar o ficheiro…':'Escolher imagem, PDF, DWG, DXF ou IFC'}</strong><span>PNG / JPG / WEBP · PDF · DWG (via DXF) · DXF ASCII · IFC2x3 / IFC4</span><input type="file" id="analysis-upload" accept="image/png,image/jpeg,image/webp,.pdf,.dxf,.ifc,.dwg,.rvt" ${analysisBusy?'disabled':''} hidden></label><div class="analysis-capabilities"><span><b>Imagem / PDF</b> Texto e cotas explícitas</span><span><b>DXF</b> Comprimentos e áreas</span><span><b>IFC</b> Elementos e quantidades</span></div><div class="analysis-progress" id="analysis-progress" role="status">${esc(analysisProgress)}</div>${analysisBusy?'<button class="small" data-analysis="cancel">Cancelar análise</button>':''}${analysisError?`<p class="error smalltext">${esc(analysisError)}</p>`:''}<div class="analysis-samples"><span class="muted">Testar com um exemplo:</span>${[['png','Imagem cotada'],['pdf','PDF técnico'],['dxf','Desenho DXF'],['ifc','Modelo IFC']].map(([ext,label])=>`<button class="small" data-analysis="sample" data-ext="${ext}" ${analysisBusy?'disabled':''}>${label} ↗</button>`).join('')}</div><p class="muted" style="font-size:10px;line-height:1.6;margin-bottom:0">Máximo: 20 MB por ficheiro; IFC até 10 MB; PDF até 5 páginas analisadas. DWG fica guardado como fonte; associa um DXF ASCII exportado para interpretar a geometria. RVT requer exportação para IFC. OCR lê texto; não compreende visualmente a peça nem deduz medidas de uma foto.</p></section>${p.files.length?`<section class="card card-pad"><div class="card-title"><h2>Anexos já disponíveis</h2></div><div class="analysis-existing">${p.files.map(f=>`<button class="small" data-analysis="existing" data-id="${esc(f.id)}" ${analysisBusy?'disabled':''}>${esc(f.name)} →</button>`).join('')}</div></section>`:''}${dwgSources(p)}${analyses(p).length?`<div class="analysis-picker"><label for="analysis-select">Análises guardadas</label><select class="field" id="analysis-select">${analyses(p).slice().reverse().map(x=>`<option value="${esc(x.id)}" ${x.id===a?.id?'selected':''}>${esc(x.name)} · ${esc(x.kind)} · ${date(x.created)}</option>`).join('')}</select></div>`:''}${a?analysisResult(a):''}`}
function quoteBlock(a){const q=a.quote,eur=v=>v.toLocaleString('pt-PT',{style:'currency',currency:'EUR'});const main=q.totals.find(t=>/total/i.test(t.label)&&!/sub/i.test(t.label));return `<section class="quote-read"><h3>Orçamento lido</h3><div class="quote-totals"><div><small>Soma das linhas</small><strong>${eur(q.sum)}</strong></div>${q.totals.map(t=>`<div><small>${esc(t.label)} (no documento)</small><strong>${eur(t.value)}</strong></div>`).join('')}</div>${main&&Math.abs(main.value-q.sum)>0.05&&!q.totals.some(t=>Math.abs(t.value-q.sum)<=0.05)?`<p class="smalltext muted">A soma das linhas lidas não bate com o total do documento: pode haver linhas que não foram lidas. Confirma no PDF.</p>`:''}<div class="table-scroll"><table class="quote-table"><thead><tr><th>Linha</th><th>Qtd.</th><th>Un.</th><th>Preço unit.</th><th>Total</th></tr></thead><tbody>${q.lines.map(l=>`<tr><td>${esc(l.desc)}</td><td>${String(l.qty).replace('.',',')}</td><td>${esc(l.unit)}</td><td>${eur(l.unitPrice)}</td><td>${eur(l.total)}</td></tr>`).join('')}</tbody></table></div><p class="smalltext muted">Os preços de um orçamento são de venda (já com margem). Para o catálogo de custos, ajusta-os antes de usar.</p><div class="pilot-ai-actions"><button type="button" class="primary small" data-analysis="quote-memory">Guardar na memória do projeto</button>${globalThis.forjaPilot?'<button type="button" class="small" data-analysis="quote-catalog">Juntar ao catálogo como referência</button>':''}</div></section>`}
function analysisResult(a){const count=a.rows?.length||0;return `<section class="card card-pad"><div class="card-title"><div><h2>${esc(a.name)}</h2><p class="smalltext muted">${esc(a.kind)} · ${count} dados extraídos · ${date(a.created)}</p></div><button class="small" data-analysis="download-result">Exportar análise ↓</button></div>${a.needsUnits?`<div class="note"><b>Falta confirmar a unidade do desenho.</b><br>Sem unidade não calculamos metros nem áreas.</div><div class="inline-settings"><label>Uma unidade do desenho corresponde a <select class="field" id="dxf-unit"><option value="4">1 milímetro</option><option value="5">1 centímetro</option><option value="6">1 metro</option><option value="1">1 polegada</option><option value="2">1 pé</option></select></label><button class="primary small" data-analysis="reanalyse" ${analysisBusy?'disabled':''}>Confirmar unidade e calcular</button></div>`:''}${a.quote?quoteBlock(a):''}<div class="analysis-stats">${[['Formato',a.stats?.schema||a.kind],['Unidade',a.stats?.units||'Indicada em cada cota'],['Elementos / entidades',a.stats?.entities??'—'],['Dados extraídos',count]].map(([k,v])=>`<div><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div>${a.notes?.length?`<details class="analysis-notes" open><summary>Âmbito e pontos a rever (${a.notes.length})</summary><ul>${a.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></details>`:''}<div id="analysis-preview">${a.shapes?.length?drawingPreview(a):analysisPreviewHTML}</div>${a.kind==='IFC'?ifcElements(a):''}${count?`<div class="toolbar" style="margin-top:22px"><input class="field search" id="analysis-search" value="${esc(analysisFilter)}" placeholder="Filtrar por elemento, layer ou material…" aria-label="Filtrar dados extraídos"><span class="smalltext muted">Revisão antes de aplicar</span></div><div id="analysis-rows">${analysisRows(a)}</div>`:!a.needsUnits?'<div class="empty">Não foram encontradas medidas explícitas utilizáveis.<br>Consulta o texto extraído e completa os dados manualmente.</div>':''}${a.rawText?`<details class="raw-text"><summary>Ver texto extraído e páginas</summary><pre>${esc(a.rawText)}</pre></details>`:''}</section>`}
function analysisRows(a){const q=analysisFilter.toLowerCase();const rows=a.rows.filter(r=>(r.label+' '+r.source+' '+(r.material||'')+' '+r.evidence).toLowerCase().includes(q));const pages=Math.max(1,Math.ceil(rows.length/analysisRowsPerPage));analysisPage=Math.min(analysisPage,pages-1);const start=analysisPage*analysisRowsPerPage;return `<div class="table-scroll"><table class="analysis-table"><thead><tr><th>Dado / origem</th><th>Valor</th><th>Revisão</th><th></th></tr></thead><tbody>${rows.slice(start,start+analysisRowsPerPage).map(r=>`<tr><td><strong>${esc(r.label)}</strong>${r.material?`<span class="tag">${esc(r.material)}</span>`:''}<small>${esc(r.source)}</small><details><summary>Evidência</summary><p>${esc(r.evidence||'')}</p></details></td><td class="analysis-value">${typeof r.value==='number'?new Intl.NumberFormat('pt-PT',{maximumFractionDigits:5}).format(r.value):esc(r.value)}<small>${esc(r.unit)}</small></td><td>${badge(r.applied?'Revisto':'Por rever')}</td><td><button class="small" data-analysis="apply" data-id="${esc(r.id)}">${r.applied?'Rever de novo':'Rever e usar'} →</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="empty">Sem resultados para este filtro.</div>':''}<div class="section-foot"><span>${rows.length} resultados · página ${analysisPage+1} / ${pages}</span><div><button class="small ghost" data-analysis="prev" ${analysisPage===0?'disabled':''}>← Anterior</button><button class="small ghost" data-analysis="next" ${analysisPage>=pages-1?'disabled':''}>Seguinte →</button></div></div>`}
function drawingPreview(a){const shapes=a.shapes||[],pts=shapes.flatMap(s=>s.points).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));if(!pts.length)return '';let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;for(const p of pts){minX=Math.min(minX,p.x);maxX=Math.max(maxX,p.x);minY=Math.min(minY,p.y);maxY=Math.max(maxY,p.y)}const w=Math.max(maxX-minX,1),h=Math.max(maxY-minY,1),pad=Math.max(w,h)*.08;return `<div class="cad-preview"><div class="cad-label">GEOMETRIA LIDA · PROJEÇÃO XY · ${shapes.length} ENTIDADES</div><svg viewBox="${minX-pad} ${-maxY-pad} ${w+pad*2} ${h+pad*2}" role="img" aria-label="Pré-visualização da geometria DXF lida">${shapes.map((s,i)=>`<polyline points="${s.points.filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)).map(p=>p.x+','+-p.y).join(' ')}" fill="${s.closed?'#97bd8612':'none'}" stroke="${['#a7ca91','#6caaa5','#d7b56d'][i%3]}" vector-effect="non-scaling-stroke" stroke-width="1.4"><title>${esc(s.layer)}</title></polyline>`).join('')}</svg><div class="cad-footer">Entidades suportadas apenas · cotas e blocos não representados</div></div>`}
function ifcElements(a){return `<details class="raw-text"><summary>Elementos BIM encontrados (${a.elements?.length||0})</summary><div class="table-scroll"><table class="analysis-table"><thead><tr><th>ID / Tipo</th><th>Nome</th><th>Material associado</th></tr></thead><tbody>${(a.elements||[]).map(e=>`<tr><td>#${e.id}<small>${esc(e.type)}</small></td><td>${esc(e.name)}<small>${esc(e.globalId)}</small></td><td>${esc(e.materials||'Não encontrado')}</td></tr>`).join('')}</tbody></table></div></details>`}
function progress(text){analysisProgress=text;if($('#analysis-progress'))$('#analysis-progress').textContent=text}
function loadScript(src,check){if(check())return Promise.resolve();return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(Error('Não foi possível carregar o leitor. Recarrega e tenta novamente.'));document.head.append(s)})}
async function ocr(image,label){await loadScript('/vendor/ocr/tesseract.min.js',()=>!!window.Tesseract);progress('A carregar o OCR local (primeira utilização pode demorar)…');ocrWorker=await Tesseract.createWorker('por+eng',1,{workerPath:'/vendor/ocr/worker.min.js',corePath:'/vendor/ocr/tesseract-core-lstm.wasm.js',langPath:'/vendor/ocr',logger:m=>{if(m.status==='recognizing text')progress(`${label} · OCR ${Math.round(m.progress*100)}%`)}});try{await ocrWorker.setParameters({tessedit_pageseg_mode:'11'});const {data}=await ocrWorker.recognize(image,{}, {text:true,blocks:true});return{text:data.text,confidence:data.confidence,blocks:data.blocks||[]}}finally{await ocrWorker?.terminate();ocrWorker=null}}
async function imageRead(file){const R=await import('./readers.mjs');const img=await createImageBitmap(file);if(img.width*img.height>30000000){img.close();throw Error('Imagem acima de 30 megapíxeis. Reduz a resolução e tenta novamente.')}const scale=Math.min(1,3200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);img.close();if(visionEnabled){progress('A interpretar imagem e pedido com IA…');visionController=new AbortController();const response=await fetch('/api/vision',{method:'POST',headers:{'Content-Type':'application/json'},signal:visionController.signal,body:JSON.stringify({text:visionContext,images:[canvas.toDataURL('image/jpeg',.9)]})});const result=await response.json();if(!response.ok)throw Error(result.error||'Falha na análise visual.');return result;}const data=await ocr(canvas,'Imagem');return{kind:'Imagem',rows:R.textRows(data.text,'OCR da imagem'),rawText:data.text,notes:['OCR experimental: lê texto e cotas impressas. Escrita manual, baixo contraste e linhas sobrepostas podem produzir erros.','Não deduz dimensões, perfis, espessuras ou materiais pela aparência da fotografia. Números sem unidade explícita não são convertidos em medidas.','Uma cota reconhecida não implica que foi associada ao elemento correto. Confirma a imagem original.'],stats:{schema:'OCR local',ocrConfidence:Math.round(data.confidence)},imageSize:{width:canvas.width,height:canvas.height}}}
async function pdfRead(file){const pdfjs=await import('./vendor/pdf/pdf.min.mjs'),R=await import('./readers.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/vendor/pdf/pdf.worker.min.mjs';const loading=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,standardFontDataUrl:'/vendor/pdf/standard_fonts/',wasmUrl:'/vendor/pdf/wasm/'});try{const pdf=await loading.promise;const out={kind:'PDF',rows:[],rawText:'',notes:[],stats:{schema:'PDF',pages:pdf.numPages}};let ocrPages=0;for(let n=1;n<=Math.min(5,pdf.numPages);n++){progress(`A ler PDF · página ${n} de ${Math.min(5,pdf.numPages)}`);const page=await pdf.getPage(n),content=await page.getTextContent();let text='',lastY=null;for(const item of content.items){if(!('str'in item))continue;const y=Math.round(item.transform[5]);text+=(lastY!==null&&Math.abs(y-lastY)>3?'\n':' ')+item.str;lastY=y;if(item.hasEOL){text+='\n';lastY=null}}if(text.trim().length<15){const base=page.getViewport({scale:1}),scale=Math.min(2.5,3000/Math.max(base.width,base.height)),viewport=page.getViewport({scale}),canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;text=(await ocr(canvas,'PDF · página '+n)).text;ocrPages++}out.rawText+=`\n--- Página ${n} ---\n${text}`;out.rows.push(...R.textRows(text,ocrPages?'PDF / OCR ou texto':'Texto PDF',n));page.cleanup()}try{const Q=await import('/pilot/import-quotes.js'),r=Q.parseQuoteText(out.rawText);if(r.lines.length){const totals=[...out.rawText.matchAll(/^[ \t]*((?:sub[ -]?total|total|iva|valor total|total geral)[^\n\d]{0,40}?)(\d{1,3}(?:[ .]\d{3})*,\d{2}|\d+(?:[.,]\d{2}))\s*€?/gim)].map(m=>({label:m[1].replace(/[:\s€]+$/,'').trim(),value:Number(m[2].replace(/[ .](?=\d{3})/g,'').replace(',','.'))})).filter(t=>Number.isFinite(t.value));out.quote={lines:r.lines,sum:Math.round(r.lines.reduce((a,l)=>a+l.total,0)*100)/100,totals,skipped:r.warnings.length};out.notes.unshift(`Parece um orçamento: ${r.lines.length} linha(s) com preço lidas${r.warnings.length?`, ${r.warnings.length} ficaram de fora por as contas não baterem certo`:''}. Confirma os valores no PDF.`)}}catch{}
out.notes.push('São lidos texto e cotas com unidade explícita. Não mede linhas do PDF nem usa a escala de impressão. Confirma cada valor na página indicada.');if(ocrPages)out.notes.push(`${ocrPages} página(s) sem texto suficiente foram processadas por OCR; podem conter erros de reconhecimento.`);if(pdf.numPages>5)out.notes.push(`PDF com ${pdf.numPages} páginas: apenas as primeiras 5 foram analisadas. Divide o ficheiro para ler as restantes.`);return out}finally{await loading.destroy()}}
function workerRead(kind,data){return new Promise((resolve,reject)=>{readerWorker=new Worker('/reader-worker.mjs',{type:'module'});const timer=setTimeout(()=>{readerWorker?.terminate();readerWorker=null;reject(Error('A leitura excedeu 90 segundos. Divide o ficheiro em partes menores.'))},90000);readerWorker.onmessage=({data:d})=>{if(d.progress){progress(`${d.progress.status} · ${Math.round(d.progress.progress*100)}%`);return}clearTimeout(timer);readerWorker.terminate();readerWorker=null;if(d.error)reject(Error(d.error));else resolve(d.result)};readerWorker.onerror=e=>{clearTimeout(timer);readerWorker?.terminate();readerWorker=null;reject(Error(e.message||'Falha no leitor de ficheiros.'))};readerWorker.postMessage({kind,...data})})}
let analysisJob=0;
async function runAnalysis(file,{fileId=null,unit=null,originDwg=null}={}){if(analysisBusy)return;const ext=file.name.split('.').pop().toLowerCase();if(ext==='dwg'){await registerDwg(file,fileId);return}if(ext==='rvt'){analysisError=ext==='dwg'?'DWG não é lido diretamente. No AutoCAD, exporta/guarda como DXF ASCII e importa esse ficheiro.':'RVT não é lido diretamente. No Revit, exporta para IFC2x3 ou IFC4 e importa o .ifc.';tab='interpretar';render();return}if(!['png','jpg','jpeg','webp','pdf','dxf','ifc'].includes(ext)){analysisError='Formato não suportado. Usa PNG, JPG, WEBP, PDF, DXF ASCII ou IFC.';render();return}if(file.size>(ext==='ifc'?10:20)*1024*1024){analysisError=`O limite para este formato é ${ext==='ifc'?10:20} MB.`;render();return}const p=project(),job=++analysisJob;analysisBusy=true;analysisError='';analysisProgress='A abrir '+file.name+'…';tab='interpretar';render();try{let result;if(ext==='dxf')result=await workerRead('DXF',{text:await file.text(),unit});else if(ext==='ifc')result=await workerRead('IFC',{buffer:await file.arrayBuffer()});else if(ext==='pdf')result=await pdfRead(file);else result=await imageRead(file);if(job!==analysisJob)return;const id=fileId||uid();if(!fileId){await filePut(id,file);p.files.push({id,name:file.name,size:file.size,type:file.type,created:now()})}result={...result,id:uid(),fileId:id,name:file.name,created:now(),originDwg,rows:result.rows.map(r=>({...r,id:uid(),applied:false,source:originDwg?`${originDwg.name} → ${file.name} · ${r.source}`:r.source}))};if(originDwg)result.notes=[...(result.notes||[]),'DXF associado manualmente ao DWG de origem. Confirma a correspondência e a versão; a conversão pode omitir entidades.'];analyses(p).push(result);analysisActive=result.id;analysisFilter='';analysisPage=0;event(p,`${file.name}: ${result.rows.length} dados extraídos por ${result.kind}. Revisão pendente.`,'Leitura de ficheiros');analysisBusy=false;analysisProgress='Análise concluída. Revê os resultados antes de os usar.';persist();render();await restoreAnalysisPreview();toast('Análise guardada no projeto.')}catch(e){if(job!==analysisJob)return;analysisBusy=false;analysisProgress='';analysisError=e.message||'Não foi possível analisar o ficheiro.';render()}finally{if(job===analysisJob)analysisBusy=false}}
async function restoreAnalysisPreview(){const a=currentAnalysis();if(!a||a.shapes?.length||a.kind==='IFC')return;const currentId=a.id;try{const blob=await fileGet(a.fileId);if(!blob)return;if(analysisPreviewUrl)URL.revokeObjectURL(analysisPreviewUrl);if(a.kind==='Imagem'){analysisPreviewUrl=URL.createObjectURL(blob);analysisPreviewHTML=`<div class="image-preview"><img src="${analysisPreviewUrl}" alt="Imagem original para verificar as cotas extraídas"><small>Imagem original · confirma as cotas e os elementos</small></div>`}else if(a.kind==='PDF'){analysisPreviewHTML='<p class="smalltext muted">Consulta a página indicada no PDF original para confirmar cada extração.</p>'}if(currentAnalysis()?.id===currentId&&$('#analysis-preview'))$('#analysis-preview').innerHTML=analysisPreviewHTML}catch{}}
function applyAnalysisRow(id){const a=currentAnalysis(),r=a.rows.find(r=>r.id===id),numeric=typeof r.value==='number';modal(`${modalHead('Rever dado extraído','Confirma o valor e a unidade no ficheiro original antes de usar.')}<div class="note"><b>${esc(r.label)}</b><br>${esc(r.source)}<br>${esc(r.evidence)}</div><form id="analysis-apply-form" data-id="${esc(id)}"><label>Destino<select class="field" name="destination" id="analysis-destination">${numeric?'<option value="quote">Adicionar linha ao orçamento</option>':''}<option value="memory">Guardar na memória como confirmado</option>${numeric&&r.unit==='m'?`<option value="width" ${r.target==='width'?'selected':''}>Largura do projeto (m)</option><option value="height" ${r.target==='height'?'selected':''}>Altura do projeto (m)</option>`:''}${!numeric&&/material/i.test(r.label)?'<option value="material">Material do projeto</option>':''}</select></label><label>${numeric?'Quantidade / valor confirmado':'Texto confirmado'}<input class="field" name="value" ${numeric?'type="number" min="0.000001" step="any"':''} required value="${esc(r.value)}"></label>${numeric?`<div class="field-grid"><label>Unidade<select class="field" name="unit">${['m','m²','m³','kg','h','un'].map(u=>`<option ${u===r.unit?'selected':''}>${u}</option>`).join('')}</select></label><label>Custo unitário (€)<input class="field" name="price" type="number" min="0" step="0.01" placeholder="Necessário para o orçamento"></label></div><label>Descrição da linha<input class="field" name="description" value="${esc(r.label)}"></label>${globalThis.forjaPilot?pilotCatalogSelect(r.unit):''}`:''}<label>Quem / como validou<input class="field" name="verification" required placeholder="Ex.: Guilherme · conferido na cota do desenho"></label><p class="muted smalltext">${r.applied?'Este dado já foi usado. Voltar a adicionar cria outra linha; confirma que não estás a duplicar quantidades.':'O orçamento só recebe valores que confirmes aqui.'}</p>${buttons('Confirmar e aplicar')}</form>`)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-analysis]');if(!b)return;const action=b.dataset.analysis;if(action==='quote-memory'||action==='quote-catalog'){const p=project(),a=analyses(p).find(x=>x.id===analysisActive),q=a?.quote;if(!q)return;if(action==='quote-memory'){const main=q.totals.find(t=>/total/i.test(t.label)&&!/sub/i.test(t.label));p.memory.unshift({id:uid(),kind:'Decisão',text:`Orçamento ${a.name}: ${q.lines.length} linha(s), soma ${q.sum.toFixed(2).replace('.',',')} €${main?`, ${main.label} ${main.value.toFixed(2).replace('.',',')} €`:''}. Linhas: ${q.lines.map(l=>`${l.desc} (${String(l.qty).replace('.',',')} ${l.unit} × ${l.unitPrice.toFixed(2).replace('.',',')} €)`).join('; ')}`.slice(0,3900),source:`${a.name} · lido do PDF, revisto pela oficina`,created:now()});event(p,'Orçamento lido guardado na memória: '+a.name,'Leitura de ficheiros');persist();render();toast('Guardado na memória do projeto.');return}try{const Q=await import('/pilot/import-quotes.js'),fold=x=>x.normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().trim(),cat=[...(state.settings.catalog||[])],have=new Set(cat.map(c=>fold(c.label)+'|'+c.unit));let n=0;for(const c of Q.toCatalog(q.lines.map(l=>({...l,unit:l.unit==='ml'?'m':l.unit})))){if(!['un','m','m²','m³','kg','h'].includes(c.unit)||have.has(fold(c.label)+'|'+c.unit))continue;cat.push({label:c.label.slice(0,180),unit:c.unit,price:Math.round(c.price*100)/100});n++}state.settings.catalog=await globalThis.forjaPilot.saveCatalog(cat);render();toast(n?`${n} artigo(s) juntos ao catálogo. Revê os preços: são de venda.`:'Estes artigos já estavam no catálogo.')}catch(err){toast(err.message||'Não foi possível juntar ao catálogo.')}return}if(action==='sample'){const ext=b.dataset.ext;try{const response=await fetch('/samples/portao-demo.'+ext);if(!response.ok)throw Error();const blob=await response.blob();await runAnalysis(new File([blob],'portao-demo.'+ext,{type:blob.type}))}catch{analysisError='Não foi possível carregar o exemplo.';render()}}if(action==='existing'){const f=project().files.find(f=>f.id===b.dataset.id);try{const blob=await fileGet(f.id);if(!blob)throw Error();await runAnalysis(new File([blob],f.name,{type:f.type}),{fileId:f.id})}catch{toast('Anexo indisponível. Volta a adicionar o ficheiro.')}}if(action==='reanalyse'){const a=currentAnalysis(),blob=await fileGet(a.fileId);if(blob)await runAnalysis(new File([blob],a.name),{fileId:a.fileId,unit:$('#dxf-unit').value,originDwg:a.originDwg||null})}if(action==='apply')applyAnalysisRow(b.dataset.id);if(action==='prev'||action==='next'){analysisPage+=action==='next'?1:-1;$('#analysis-rows').innerHTML=analysisRows(currentAnalysis())}if(action==='download-result'){const a=currentAnalysis();download(new Blob([JSON.stringify(a,null,2)],{type:'application/json'}),a.name+'-analise.json')}if(action==='cancel'){analysisJob++;visionController?.abort();readerWorker?.terminate();readerWorker=null;await ocrWorker?.terminate();ocrWorker=null;analysisBusy=false;analysisProgress='Análise cancelada.';render()}});
document.addEventListener('change',async e=>{if(e.target.id==='analysis-upload'&&e.target.files[0])await runAnalysis(e.target.files[0]);if(e.target.id==='analysis-select'){analysisActive=e.target.value;analysisPage=0;analysisFilter='';analysisPreviewHTML='';render();await restoreAnalysisPreview()}});
document.addEventListener('input',e=>{if(e.target.id==='analysis-search'){analysisFilter=e.target.value;analysisPage=0;$('#analysis-rows').innerHTML=analysisRows(currentAnalysis())}});
document.addEventListener('submit',e=>{if(e.target.id!=='analysis-apply-form')return;e.preventDefault();const f=new FormData(e.target),a=currentAnalysis(),r=a.rows.find(r=>r.id===e.target.dataset.id),p=project(),destination=f.get('destination'),numeric=typeof r.value==='number',value=numeric?Number(f.get('value')):String(f.get('value')).trim(),unit=f.get('unit'),verification=String(f.get('verification')).trim();if(!verification||!value||(numeric&&(!Number.isFinite(value)||value<=0))){toast('Confirma o valor e identifica a validação.');return}if(['width','height'].includes(destination)&&unit!=='m'){toast('Para largura ou altura do projeto, confirma o valor em metros.');return}const source=`${a.name} · ${r.source} · revisto: ${verification}${destination==='quote'&&e.target.dataset.priceSource?' · '+e.target.dataset.priceSource:''}`;if(destination==='quote'){if(f.get('price')===''||!Number.isFinite(Number(f.get('price')))||Number(f.get('price'))<0){toast('Indica o custo unitário antes de adicionar ao orçamento.');return}dirty(p);p.lines.push({id:uid(),desc:String(f.get('description')||r.label),qty:value,unit,price:Number(f.get('price')),source,analysisId:a.id,analysisRowId:r.id});event(p,'Dado extraído validado e adicionado ao orçamento: '+r.label,source)}else if(['width','height','material'].includes(destination)){dirty(p);const before=p.fields[destination];p.fields[destination]=String(value);event(p,`Dado do projeto atualizado: ${destination} de ${before||'por indicar'} para ${value}.`,source)}r.applied=true;r.appliedAt=now();r.verifiedBy=verification;r.confirmedValue=value;r.confirmedUnit=unit||'';p.memory.unshift({id:uid(),kind:'Confirmado',text:`${r.label}: ${value} ${unit||''}. ${destination==='quote'?'Adicionado ao orçamento.':destination==='memory'?'Registado na memória.':'Dado do projeto atualizado.'}`,source,created:now()});persist();closeModal();render();toast('Dado confirmado e aplicado com a sua fonte.');});

function dwgSources(p){const files=p.files.filter(f=>/\.dwg$/i.test(f.name));if(!files.length)return '';return `<section class="card card-pad"><h2>Fontes DWG</h2><p class="smalltext muted">Original guardado. Exporta a mesma versão para DXF ASCII no teu CAD ou no ODA File Converter e associa-a aqui. Ainda não há leitura direta nem conversão automática.</p>${files.map(f=>`<div class="file-row"><div class="grow"><strong>${esc(f.name)}</strong><small>${analyses(p).some(a=>a.originDwg?.id===f.id)?'Tem DXF associado · resultados sujeitos a revisão':'Pendente de DXF · sem quantidades extraídas'}</small></div><label class="small">Associar e ler DXF<input type="file" class="dwg-dxf-upload" data-dwg-id="${esc(f.id)}" accept=".dxf" ${analysisBusy?'disabled':''} hidden></label></div>`).join('')}</section>`}
async function registerDwg(file,fileId){
 if(file.size>20*1024*1024){analysisError='O limite para DWG é 20 MB.';render();return}
 const signature=new TextDecoder().decode(await file.slice(0,6).arrayBuffer());
 if(!/^AC[0-9]{4}$/.test(signature)){analysisError='Cabeçalho DWG não reconhecido. Confirma o formato no CAD; mudar a extensão não converte o ficheiro.';render();return}
 const p=project();
 if(!fileId){const id=uid();await filePut(id,file);p.files.push({id,name:file.name,size:file.size,type:file.type,created:now()});event(p,`${file.name}: fonte DWG guardada, pendente de DXF para leitura.`,'Importação DWG');persist()}
 analysisError='';analysisProgress='DWG guardado como fonte. Associa o DXF exportado na secção Fontes DWG.';tab='interpretar';render();
}
document.addEventListener('change',async e=>{
 if(!e.target.matches('.dwg-dxf-upload')||!e.target.files[0]||analysisBusy)return;
 const original=project().files.find(f=>f.id===e.target.dataset.dwgId),file=e.target.files[0];
 if(!original)return;
 if(!/\.dxf$/i.test(file.name)){analysisError='Associa um ficheiro DXF ASCII.';render();return}
 await runAnalysis(file,{originDwg:{id:original.id,name:original.name}});
});
